import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState} from '../src/model.js';
const dir='检查记录/填写引导_20261022';await fs.mkdir(dir+'/实际截图',{recursive:true});const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});const p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.setDefaultNavigationTimeout(30000);p.on('pageerror',e=>errors.push(e.message));
async function load(route='/assessment?tab=资料经历',s='PT01',width=1440,lang='zh'){await p.setViewportSize({width,height:width===390?844:1000});await p.goto('http://127.0.0.1:5184/plan');await p.evaluate(({k,s,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{k:KEY,s:typeof s==='string'?scenarioState(s):s,lang});await p.goto('http://127.0.0.1:5184'+route);await p.locator('.page-surface').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function fillPart(key,value){await p.locator('.experience-story-nav button').nth(['context','action','outcome'].indexOf(key)).click();await p.locator('#experience-'+key).fill(value);}
async function shot(name,selector='.experience-writer'){const el=p.locator(selector);await el.evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/实际截图/'+name+'-视口.png'});const v=p.viewportSize(),b=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(b.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await el.screenshot({path:dir+'/实际截图/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,700));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('空表有具体回忆问题和只读示例，不默认选择SQL；错误定位且不丢输入',async()=>{await load();await shot('1440-引导起点');await p.locator('.experience-optional>summary').click();assert.equal(await p.getByLabel('关联技能（本人选择，非自动判断）',{exact:true}).inputValue(),'未知');assert.equal((await state()).claims.length,0);await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal(await p.locator('#experience-action').evaluate(e=>document.activeElement===e),true);await fillPart('action','本人整理了活动资料');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal(await p.locator('#experience-title').evaluate(e=>document.activeElement===e),true);assert.equal(await p.locator('#experience-action').inputValue(),'本人整理了活动资料');assert.equal((await state()).claims.length,0);});
await check('跟着问题填写、离开返回、保存待确认并进入原确认回执',async()=>{await load();await fillPart('context','课程作业需要整理资料（合成验收）');await fillPart('action','我记录了空白条目与处理理由（合成验收）');await fillPart('outcome','留下清单，结论尚未重复检查（合成验收）');await p.locator('#experience-title').fill('本人合成课程记录');await p.goto('http://127.0.0.1:5184/plan');await p.goto('http://127.0.0.1:5184/assessment?tab=资料经历');assert.match(await p.locator('#experience-action').inputValue(),/处理理由/);await p.locator('.experience-preview>summary').click();assert.match(await p.locator('.experience-preview').innerText(),/合成验收/);await shot('1440-本人输入与预览');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();let s=await state();assert.equal(s.claims.length,1);assert.equal(s.claims[0].status,'待确认');assert.equal(s.claims[0].skill,'未知');assert.equal(s.claims[0].guidedParts,undefined);assert.match(s.claims[0].text,/课程作业需要整理资料/);assert.doesNotMatch(s.claims[0].text,/课程要求整理一份练习表/);assert.equal(s.analysis,null);await p.getByRole('button',{name:'修正 / 确认此项',exact:true}).click();await p.getByRole('button',{name:'确认这一项并查看回执',exact:true}).click();s=await state();assert.equal(s.claims[0].status,'已确认');assert.equal(s.analysis,null);});
await check('粘贴原文和引导草稿分别保留，保存当前方式；旧草稿不被覆盖',async()=>{await load();await fillPart('action','引导方式自己的草稿');await p.getByRole('button',{name:'粘贴原文',exact:true}).click();assert.equal(await p.locator('#experience-raw').inputValue(),'引导方式自己的草稿');await p.locator('#experience-raw').fill('本人旧原文\n保留第二行（合成）');await p.getByRole('button',{name:'分步填写',exact:true}).click();assert.equal(await p.locator('#experience-action').inputValue(),'引导方式自己的草稿');await p.getByRole('button',{name:'粘贴原文',exact:true}).click();await p.locator('#experience-title').fill('本人粘贴记录');await shot('1440-粘贴原文');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal((await state()).claims[0].text,'本人旧原文\n保留第二行（合成）');const legacy=scenarioState('PT01');legacy.claimDraft={...legacy.claimDraft,title:'历史标题',text:'历史草稿原句',skill:'Python'};await load('/assessment?tab=资料经历',legacy);assert.equal(await p.locator('#experience-raw').inputValue(),'历史草稿原句');await p.getByRole('button',{name:'分步填写',exact:true}).click();assert.equal(await p.locator('#experience-action').inputValue(),'历史草稿原句');const skillOnly=scenarioState('PT01');skillOnly.claimDraft.skill='Figma';await load('/assessment?tab=资料经历',skillOnly);await p.locator('.experience-optional>summary').click();assert.equal(await p.getByLabel('其他技能名称（可选）',{exact:true}).inputValue(),'Figma');await fillPart('action','后来补写的本人内容');await p.locator('#experience-title').fill('旧技能选择保留（合成）');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal((await state()).claims[0].skill,'Figma');});
await check('更换类型保留输入、更新提示；自定义技能只在本人选择后保存',async()=>{await load();await fillPart('action','自己整理活动报名');await p.getByLabel('经历类型',{exact:true}).selectOption('校园经历');assert.match(await p.locator('.experience-question:visible .experience-question-title').innerText(),/配合/);assert.equal(await p.locator('#experience-action').inputValue(),'自己整理活动报名');await p.locator('.experience-optional>summary').click();await p.getByLabel('关联技能（本人选择，非自动判断）',{exact:true}).selectOption('其他');await p.getByLabel('其他技能名称（可选）',{exact:true}).fill('Figma');await p.locator('#experience-title').fill('校园材料（合成）');await p.reload();assert.equal(await p.locator('#experience-action').inputValue(),'自己整理活动报名');await p.locator('.experience-optional>summary').click();assert.equal(await p.getByLabel('其他技能名称（可选）',{exact:true}).inputValue(),'Figma');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal((await state()).claims[0].skill,'Figma');assert.equal((await state()).claims[0].type,'校园经历');});
await check('手机、中英文、长输入与保存出口不横向溢出',async()=>{for(const [name,lang] of [['390-引导起点','zh'],['390-英文引导','en']]){await load('/assessment?tab=资料经历','PT01',390,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await shot(name);if(lang==='en')assert.equal((await p.locator('.experience-writer').innerText()).match(/[\u4e00-\u9fff]+/g),null);else{await p.locator('.experience-question:not([hidden]) .experience-inline-example>summary').click();assert.equal((await state()).claimDraft.text,'');await shot('390-就地参考');}}await load('/assessment?tab=资料经历','PT01',390);await fillPart('action','一次实际记录与未知事项'.repeat(60));await p.locator('#experience-title').fill('长标题材料'.repeat(25));await p.locator('.experience-preview>summary').click();assert.equal(await p.locator('.experience-writer').evaluate(e=>e.scrollWidth>e.clientWidth),false);assert.match(await p.locator('.flow-progress').innerText(),/保存并核对经历/);assert.doesNotMatch(await p.locator('.flow-progress').innerText(),/保存为待确认候选/);const button=p.getByRole('button',{name:'保存并核对经历',exact:true});await button.scrollIntoViewIfNeeded();const box=await button.boundingBox(),flow=await p.locator('.flow-progress').boundingBox();assert.ok(box.y+box.height<flow.y+1);await p.screenshot({path:dir+'/实际截图/390-长输入与保存出口.png'});});
await check('同类写作提示关联真实输入，不改变原保存对象或任务状态',async()=>{await load('/work/task-demo?tab=尝试与反馈','PT06');await p.locator('#task-draft-writing-hint').waitFor();assert.equal(await p.getByLabel('产物文本（每次提交形成独立版本）',{exact:true}).getAttribute('aria-describedby'),'task-draft-writing-hint');await shot('1440-任务就地提示','.quality-task-layout');const externalState=scenarioState('PT05');externalState.stage='S1';externalState.tasks[0].mode='S1';await load('/plan?tab=执行&practice=task-demo&step=record',externalState);await p.locator('#external-result-writing-hint').waitFor();await p.getByLabel('实际行动与结果（自动保留）',{exact:true}).fill('合成站外过程记录');await p.getByRole('button',{name:'保存实践记录',exact:true}).click();assert.equal((await state()).tasks[0].note,'合成站外过程记录');assert.equal((await state()).tasks[0].status,externalState.tasks[0].status);await shot('1440-站外记录提示','.external-practice');await load('/careers?tab=我的机会','PT05');await p.getByRole('button',{name:'记录本人申请 / 面试 / 结果',exact:true}).click();assert.equal(await p.getByLabel('本人笔记',{exact:true}).getAttribute('aria-describedby'),'job-event-note-hint');await shot('1440-求职事件提示','dialog[open]');});
assert.deepEqual(errors,[]);results.push({name:'浏览器运行时错误',status:'pass',count:0});
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}if(results.some(r=>r.status==='fail'))process.exitCode=1;
